import{_ as a,c as t,o as i,aj as r}from"./chunks/framework.Id7s26SP.js";const m=JSON.parse('{"title":"Interface: InvitationsAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/InvitationsAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/InvitationsAPI.md"}'),n={name:"reference/js-bao-wss-client/api/interfaces/InvitationsAPI.md"};function o(s,e,d,c,l,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / InvitationsAPI</p><h1 id="interface-invitationsapi" tabindex="-1">Interface: InvitationsAPI <a class="header-anchor" href="#interface-invitationsapi" aria-label="Permalink to “Interface: InvitationsAPI”">​</a></h1><p>Sub-API for app-level invitations and deferred grants.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="accept" tabindex="-1">accept() <a class="header-anchor" href="#accept" aria-label="Permalink to “accept()”">​</a></h3><blockquote><p><strong>accept</strong>(<code>inviteToken</code>): <code>Promise</code>&lt;<a href="./AcceptInviteResult.html"><code>AcceptInviteResult</code></a>&gt;</p></blockquote><p>Accept an invitation via its invite token.</p><p>For authenticated users whose session already exists (e.g. they signed up with a different email than the invited one, or were invited after signup). The server marks the invitation accepted (write-once) and binds all pending deferred grants linked to it to the caller&#39;s userId.</p><p>Throws on any invite-token failure (invalid / expired / already-accepted) with <code>AUTH_CODES.INVITE_TOKEN_INVALID</code>. The server returns a uniform 401 + <code>INVITE_TOKEN_INVALID</code> for all failure modes rather than distinct codes, so the response does not reveal whether an underlying invitation exists.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="invitetoken" tabindex="-1">inviteToken <a class="header-anchor" href="#invitetoken" aria-label="Permalink to “inviteToken”">​</a></h5><p><code>string</code></p><p>The invitation token from the accept URL</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AcceptInviteResult.html"><code>AcceptInviteResult</code></a>&gt;</p><hr><h3 id="create" tabindex="-1">create() <a class="header-anchor" href="#create" aria-label="Permalink to “create()”">​</a></h3><blockquote><p><strong>create</strong>(<code>params</code>): <code>Promise</code>&lt;<a href="./AppInvitationInfo.html"><code>AppInvitationInfo</code></a>&gt;</p></blockquote><p>Create an app-level invitation. Members can create invitations when <code>memberInvitationsEnabled</code> is true. Admins/owners can always create invitations.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="params" tabindex="-1">params <a class="header-anchor" href="#params" aria-label="Permalink to “params”">​</a></h5><p><a href="./CreateInvitationParams.html"><code>CreateInvitationParams</code></a></p><p>Invitation details</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AppInvitationInfo.html"><code>AppInvitationInfo</code></a>&gt;</p><hr><h3 id="delete" tabindex="-1">delete() <a class="header-anchor" href="#delete" aria-label="Permalink to “delete()”">​</a></h3><blockquote><p><strong>delete</strong>(<code>invitationId</code>): <code>Promise</code>&lt;{ <code>message</code>: <code>string</code>; <code>success</code>: <code>boolean</code>; }&gt;</p></blockquote><p>Delete (revoke) an app-level invitation.</p><p>Admins and owners can revoke any invitation. A member can revoke only invitations they created themselves (403 otherwise). Revoking an active invitation frees the member&#39;s quota. Also cascade-deletes any linked deferred grants.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="invitationid" tabindex="-1">invitationId <a class="header-anchor" href="#invitationid" aria-label="Permalink to “invitationId”">​</a></h5><p><code>string</code></p><p>The invitation to delete</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;{ <code>message</code>: <code>string</code>; <code>success</code>: <code>boolean</code>; }&gt;</p><hr><h3 id="get" tabindex="-1">get() <a class="header-anchor" href="#get" aria-label="Permalink to “get()”">​</a></h3><blockquote><p><strong>get</strong>(<code>invitationId</code>): <code>Promise</code>&lt;<a href="./AppInvitationInfo.html"><code>AppInvitationInfo</code></a>&gt;</p></blockquote><p>Fetch a single app invitation by id.</p><p>Returns the full invitation envelope, including <code>inviteToken</code> so callers can build their own accept-page CTA (e.g. <code>${baseUrl}/invite/accept?inviteToken=…</code>). The platform does not compose accept URLs because apps own their own accept-page routing.</p><p>Permissions: app admin/owner, OR the invitation&#39;s original inviter. Members who did not create the invitation receive 403 — <code>inviteToken</code> is a bearer credential, so read access is intentionally narrow.</p><p>Legacy invitations with no token are lazily upgraded on first read.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="invitationid-1" tabindex="-1">invitationId <a class="header-anchor" href="#invitationid-1" aria-label="Permalink to “invitationId”">​</a></h5><p><code>string</code></p><p>The invitation to look up</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./AppInvitationInfo.html"><code>AppInvitationInfo</code></a>&gt;</p><hr><h3 id="list" tabindex="-1">list() <a class="header-anchor" href="#list" aria-label="Permalink to “list()”">​</a></h3><blockquote><p><strong>list</strong>(<code>options?</code>): <code>Promise</code>&lt;<a href="./InvitationListResult.html"><code>InvitationListResult</code></a>&gt;</p></blockquote><p>List app-level invitations.</p><p>Admins and owners see the full app list. Members see only the invitations they created themselves — the <code>memberInvitationsEnabled</code> flag gates <em>creating</em> invitations, not listing your own (a member can always see and revoke invitations they already sent). A member with no invitations of their own gets an empty list, not a 403.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./InvitationListOptions.html"><code>InvitationListOptions</code></a></p><p>Pagination options</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./InvitationListResult.html"><code>InvitationListResult</code></a>&gt;</p><hr><h3 id="listdeferredgrants" tabindex="-1"><s>listDeferredGrants()</s> <a class="header-anchor" href="#listdeferredgrants" aria-label="Permalink to “listDeferredGrants()”">​</a></h3><blockquote><p><strong>listDeferredGrants</strong>(<code>options?</code>): <code>Promise</code>&lt;<a href="./DeferredGrantListResult.html"><code>DeferredGrantListResult</code></a>&gt;</p></blockquote><p>List pending deferred grants (admin/owner only). Deferred grants are permissions/memberships created for users who haven&#39;t signed up yet.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><a href="./DeferredGrantListOptions.html"><code>DeferredGrantListOptions</code></a></p><p>Filter and pagination options</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DeferredGrantListResult.html"><code>DeferredGrantListResult</code></a>&gt;</p><h4 id="deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated" aria-label="Permalink to “Deprecated”">​</a></h4><p>The deferred-grants API is deprecated. A pending invitation is listed on its resource (<code>listPendingInvitations</code> on <code>client.documents</code>, <code>client.db3.permissions(id)</code>, <code>client.groups</code> and <code>client.collections</code>) and revoked there with <code>revokePendingInvitation</code>.</p><hr><h3 id="preview" tabindex="-1">preview() <a class="header-anchor" href="#preview" aria-label="Permalink to “preview()”">​</a></h3><blockquote><p><strong>preview</strong>(<code>inviteToken</code>): <code>Promise</code>&lt;<a href="./InvitationPreview.html"><code>InvitationPreview</code></a>&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>Preview an invitation by its token, with or without a session.</p><p>Answers what the invitation offers before its holder signs in: the app&#39;s name and icon, the inviter&#39;s name, the offered role, what it shares and its status (<code>pending</code>, <code>expired</code> or <code>accepted</code>). Works in every app. An unknown or revoked token rejects with <code>INVITATION_NOT_FOUND</code>; failed previews count toward the same per-address limit as failed accepts.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="invitetoken-1" tabindex="-1">inviteToken <a class="header-anchor" href="#invitetoken-1" aria-label="Permalink to “inviteToken”">​</a></h5><p><code>string</code></p><p>The invitation token from the invitation link</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./InvitationPreview.html"><code>InvitationPreview</code></a>&gt;</p><h4 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h4><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> preview</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.invitations.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">preview</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(inviteToken);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (preview.status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;pending&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">showInvite</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(preview.inviterName, preview.shared);</span></span></code></pre></div><hr><h3 id="quota" tabindex="-1">quota() <a class="header-anchor" href="#quota" aria-label="Permalink to “quota()”">​</a></h3><blockquote><p><strong>quota</strong>(): <code>Promise</code>&lt;<a href="./InvitationQuota.html"><code>InvitationQuota</code></a>&gt;</p></blockquote><p>Check the current user&#39;s invitation quota. Admins/owners always get <code>unlimited: true</code>.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./InvitationQuota.html"><code>InvitationQuota</code></a>&gt;</p><hr><h3 id="revokedeferredgrant" tabindex="-1"><s>revokeDeferredGrant()</s> <a class="header-anchor" href="#revokedeferredgrant" aria-label="Permalink to “revokeDeferredGrant()”">​</a></h3><blockquote><p><strong>revokeDeferredGrant</strong>(<code>deferredId</code>, <code>type</code>): <code>Promise</code>&lt;<a href="./DeferredGrantRevokeResult.html"><code>DeferredGrantRevokeResult</code></a>&gt;</p></blockquote><p>Revoke a deferred grant. Admins/owners can revoke any; the original granter can revoke their own.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="deferredid" tabindex="-1">deferredId <a class="header-anchor" href="#deferredid" aria-label="Permalink to “deferredId”">​</a></h5><p><code>string</code></p><p>The deferred grant to revoke</p><h5 id="type" tabindex="-1">type <a class="header-anchor" href="#type" aria-label="Permalink to “type”">​</a></h5><p><code>&quot;document&quot;</code> | <code>&quot;group&quot;</code></p><p>Whether this is a &quot;document&quot; or &quot;group&quot; deferred grant</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./DeferredGrantRevokeResult.html"><code>DeferredGrantRevokeResult</code></a>&gt;</p><h4 id="deprecated-1" tabindex="-1">Deprecated <a class="header-anchor" href="#deprecated-1" aria-label="Permalink to “Deprecated”">​</a></h4><p>The deferred-grants API is deprecated. Revoke a pending invitation on its resource with <code>revokePendingInvitation</code> (on <code>client.documents</code>, <code>client.db3.permissions(id)</code>, <code>client.groups</code> and <code>client.collections</code>), keyed by the <code>invitationId</code> its list returns.</p>',109)])])}const v=a(n,[["render",o]]);export{m as __pageData,v as default};
